<?php $filter_action=base_url('weighted_exam/marks');$show_session=true;$show_subject=true;$show_component=true;$examId=$examId;$classId=$classId;$sectionId=$sectionId;$examSubjectId=$examSubjectId;$this->load->view('weighted_exam/_filters',get_defined_vars());?>
<div id="subject-load-message" class="alert" style="display:none"></div>
<script>
$(function(){
 var $session=$('select[name="session_id"]'),$exam=$('select[name="exam_id"]'),$class=$('select[name="class_id"]'),$section=$('select[name="section_id"]'),$subject=$('select[name="exam_subject_id"]'),$component=$('select[name="component"]'),subjectData={};
 function message(text,error){$('#subject-load-message').removeClass('alert-info alert-danger alert-warning').addClass(error?'alert-danger':'alert-warning').text(text).toggle(!!text);}
 function resetSubject(){subjectData={};$subject.html('<option value="">Select Subject</option>').trigger('change.select2');$component.html('<option value="">Select Component</option>');}
 function filterExams(){var session=$session.val();$exam.find('option').each(function(){if(!this.value)return;$(this).prop('disabled',session&&$(this).data('session').toString()!==session.toString());});if($exam.find('option:selected').prop('disabled'))$exam.val('').trigger('change.select2');resetSubject();}
 function components(id,selected){$component.html('<option value="">Select Component</option>');var item=subjectData[id];if(!item)return;$.each(item.components,function(_,c){$component.append($('<option>',{value:c.id,text:c.label+' ('+c.full_marks+')',selected:c.id===selected}));});}
 function loadSubjects(selectedSubject,selectedComponent){resetSubject();message('Loading configured subjects...',false);if(!$exam.val()||!$class.val()||!$section.val()){message('Select examination, class and section to load subjects.',false);return;}$.ajax({url:base_url+'weighted_exam/subjects_json',data:{branch_id:$('select[name="branch_id"]').val()||'','exam_id':$exam.val(),class_id:$class.val(),section_id:$section.val()},dataType:'json'}).done(function(response){if(response.status!=='success')throw new Error(response.message||'Subject loading failed.');$.each(response.subjects,function(_,s){subjectData[s.id]=s;$subject.append($('<option>',{value:s.id,text:s.name,selected:String(s.id)===String(selectedSubject)}));});$subject.trigger('change.select2');if(selectedSubject)components(String(selectedSubject),selectedComponent);message(response.message||'',false);}).fail(function(xhr){var text='Unable to load subjects. Please verify exam subject configuration and permissions.';if(xhr.responseJSON&&xhr.responseJSON.message)text=xhr.responseJSON.message;message(text,true);});}
 $session.on('change',filterExams);$exam.add($section).on('change',function(){loadSubjects('','');});$class.on('change',function(){resetSubject();$section.html('<option value="">Loading sections...</option>').trigger('change.select2');if(!this.value)return;$.ajax({url:base_url+'ajax/getSectionByClass',type:'POST',data:{class_id:this.value,all:0,multi:0}}).done(function(html){$section.html(html).val('').trigger('change.select2');message('Select a section to load configured subjects.',false);}).fail(function(){message('Unable to load sections for the selected class.',true);});});$subject.on('change',function(){components($(this).val(),'');});
 if($session.length)filterExams();loadSubjects('<?=html_escape($examSubjectId)?>','<?=html_escape($component)?>');
});
</script>
<?php if($students): $chosen=null;foreach($subjects as $s)if($s['id']==$examSubjectId)$chosen=$s;$cfg=$chosen&&isset($chosen['components'][$component])?$chosen['components'][$component]:null;?>
<?=form_open('weighted_exam/marks')?><?php foreach(['branch_id'=>$branch_id,'session_id'=>$sessionId,'exam_id'=>$examId,'class_id'=>$classId,'section_id'=>$sectionId,'exam_subject_id'=>$examSubjectId,'component'=>$component] as $k=>$v):?><input type="hidden" name="<?=$k?>" value="<?=$v?>"><?php endforeach?>
<section class="panel"><header class="panel-heading"><h4 class="panel-title"><i class="fas fa-marker"></i> Bulk Marks Entry — <?=html_escape($chosen['subject_name'])?> / <?=ucwords(str_replace('_',' ',$component))?></h4></header><div class="panel-body table-responsive"><table class="table table-bordered table-hover"><thead><tr><th>Roll</th><th>Register No.</th><th>Student</th><th>Full Marks</th><th>Obtained Marks</th><th>Status</th></tr></thead><tbody><?php foreach($students as $i=>$s):$m=isset($marks[$s['enroll_id']])?$marks[$s['enroll_id']]:null;?><tr><td><?=$s['roll']?></td><td><?=html_escape($s['register_no'])?></td><td><?=html_escape($s['student_name'])?></td><td><?=$cfg?number_format($cfg['full_marks'],2):''?></td><td><input type="number" class="form-control mark-input" step="0.01" min="0" max="<?=$cfg?$cfg['full_marks']:0?>" name="marks[<?=$s['enroll_id']?>][obtained_marks]" value="<?=$m&&$m['obtained_marks']!==null?$m['obtained_marks']:''?>" autocomplete="off"></td><td><select class="form-control mark-status" name="marks[<?=$s['enroll_id']?>][status]"><?php foreach(['present'=>'Present','absent'=>'Absent','exempt'=>'Exempt','not_entered'=>'Not Entered'] as $k=>$v):?><option value="<?=$k?>" <?=($m?$m['status']:'not_entered')===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></td></tr><?php endforeach?></tbody></table></div><footer class="panel-footer text-right"><button name="save_marks" value="1" class="btn btn-default"><i class="fas fa-save"></i> Bulk Save Marks</button></footer></section><?=form_close()?>
<script>$(function(){function sync($s){var $i=$s.closest('tr').find('.mark-input');if($s.val()==='present'){$i.prop('disabled',false);}else{$i.val('').prop('disabled',true);}}$('.mark-status').each(function(){sync($(this));}).on('change',function(){sync($(this));});$('.mark-input').on('keydown',function(e){if(e.key==='Enter'){e.preventDefault();var a=$('.mark-input:enabled'),i=a.index(this);a.eq(i+1).focus().select();}});});</script>
<?php elseif($examId&&$examSubjectId):?><div class="alert alert-warning">No active enrolled students were found, or this component is not configured.</div><?php endif?>

